WITH c(master_id,instance_id,entry_id,object_id,title_snapshot,disc_snapshot,track_snapshot) AS (VALUES
('sm-upload-46552f7f-fae','si-upload-44fe3603-d9d','se-f61c589302604ee7abceaaa49c326274','obj_b41f2e2f400a2848','02 笼中藤',NULL,NULL),
('sm-upload-56571117-ce0','si-upload-755c90bd-08e','se-b6cec9df1fd4418f83ab3c8ea41417b7','obj_f0f6f92ad590ad8b','03 梦醉酒醒',NULL,NULL),
('sm-upload-a0ec2a9f-fe9','si-upload-6abdc96b-ed7','se-ce4c5b4822b64d7680f4805de21bd379','obj_944f0fa40ed327d4','04 问心',NULL,NULL),
('sm-upload-f3f4157d-6ee','si-upload-ad39141e-329','se-7eaf7be9cdf24b6aa47a50847e32ce21','obj_cb8abfa22e0bd72b','01 双星系统',NULL,NULL)
)
SELECT 'batch_011_4131044b_wav_04' AS batch_id,(SELECT COUNT(*) FROM c) AS expected_masters,(SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-4d81506c43c249f3b64dc32c47d15111' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1) AS exact_pending_storage_matches,(SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-4d81506c43c249f3b64dc32c47d15111' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1) AS metadata_snapshot_matches,(SELECT COUNT(*) FROM albums WHERE id='al-3a2710cebd830ec6fee4ae8c4131044b') AS target_album_rows,(SELECT COUNT(*) FROM (SELECT lower(trim(sm.title)) FROM c JOIN song_masters sm ON sm.id=c.master_id GROUP BY lower(trim(sm.title)) HAVING COUNT(*)>1)) AS duplicate_title_groups,(SELECT COUNT(*) FROM (SELECT COALESCE(sm.disc,0),sm.track FROM c JOIN song_masters sm ON sm.id=c.master_id WHERE sm.track IS NOT NULL GROUP BY COALESCE(sm.disc,0),sm.track HAVING COUNT(*)>1)) AS duplicate_disc_track_groups,(SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-4d81506c43c249f3b64dc32c47d15111' AND sm.album_id!='pending-uploads') AS other_album_members,(SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-4d81506c43c249f3b64dc32c47d15111' AND sm.album_id!='pending-uploads' AND sm.id NOT IN ('')) AS unallowlisted_other_members,(SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE sm.id IN ('') AND sm.album_id IN ('') AND se.source_id='r2-local' AND se.parent_id='se-4d81506c43c249f3b64dc32c47d15111' AND lower(si.suffix)='wav') AS allowlisted_other_members;
